const navy = Color(0xFF071827), navy2 = Color(0xFF102B40), gold = Color(0xFFD7A84A), gold2 = Color(0xFFF2CC75), page = Color(0xFFF5F7F9);
const green = Color(0xFF27B765), blue = Color(0xFF2D98E6), purple = Color(0xFF7655D8), orange = Color(0xFFF39A2B), teal = Color(0xFF23AEBE);
String hashPass(String v) => sha256.convert(utf8.encode(v)).toString();

class User { User(this.username,this.name,this.role,this.password); String username,name,role,password; Map<String,dynamic> toJson()=>{'u':username,'n':name,'r':role,'p':password}; factory User.fromJson(Map<String,dynamic> j)=>User('${j['u']??''}','${j['n']??''}','${j['r']??'مشاور'}','${j['p']??''}'); }
class Property { Property({required this.code,required this.type,required this.title,required this.address,required this.owner,required this.phone,required this.price,required this.area,required this.rooms,required this.year,required this.agent,this.link='' }); String code,type,title,address,owner,phone,price,area,rooms,year,agent,link; Map<String,dynamic> toJson()=>{'c':code,'t':type,'ti':title,'a':address,'o':owner,'ph':phone,'pr':price,'ar':area,'ro':rooms,'y':year,'ag':agent,'l':link}; factory Property.fromJson(Map<String,dynamic> j)=>Property(code:'${j['c']??''}',type:'${j['t']??'آپارتمان'}',title:'${j['ti']??''}',address:'${j['a']??''}',owner:'${j['o']??''}',phone:'${j['ph']??''}',price:'${j['pr']??''}',area:'${j['ar']??''}',rooms:'${j['ro']??''}',year:'${j['y']??''}',agent:'${j['ag']??''}',link:'${j['l']??''}'); }
final properties=<Property>[]; final clients=<String>[]; final meetings=<String>[]; User? currentUser; bool get isManager=>currentUser?.role=='مدیر'||currentUser?.role=='مدیر فروش';

class Store { static Future<SharedPreferences> get prefs=>SharedPreferences.getInstance(); static Future<List<User>> users() async { final p=await prefs; final raw=p.getString('users'); if(raw==null){final u=[User('admin','مهندس مجتبی صفری','مدیر',hashPass('1234')),User('sales','خانم طهماسبی پور','مدیر فروش',hashPass('1234')),User('moshaver1','مشاور اول','مشاور',hashPass('1234'))]; await saveUsers(u); return u;} return (jsonDecode(raw) as List).map((e)=>User.fromJson(Map<String,dynamic>.from(e))).toList(); } static Future<void> saveUsers(List<User> u) async=>(await prefs).setString('users',jsonEncode(u.map((e)=>e.toJson()).toList())); static Future<void> load() async {final p=await prefs; try{final raw=jsonDecode(p.getString('properties')??'[]') as List; properties..clear()..addAll(raw.map((e)=>Property.fromJson(Map<String,dynamic>.from(e))));}catch(_){properties.clear();} clients..clear()..addAll(p.getStringList('clients')??[]); meetings..clear()..addAll(p.getStringList('meetings')??[]);} static Future<void> save() async {final p=await prefs;await p.setString('properties',jsonEncode(properties.map((e)=>e.toJson()).toList()));await p.setStringList('clients',clients);await p.setStringList('meetings',meetings);} static Future<bool> dark() async=>(await prefs).getBool('dark')??false; static Future<void> setDark(bool v) async=>(await prefs).setBool('dark',v); }

