class _CommissionState extends State<Commission>{final amount=TextEditingController();final rate=TextEditingController(text:'0.5');double result=0;@override Widget build(BuildContext c)=>Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:600),child:Card(margin:const EdgeInsets.all(20),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.calculate,color:gold,size:52),const Text('محاسبه کمیسیون',style:TextStyle(fontSize:23,fontWeight:FontWeight.bold)),const SizedBox(height:18),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'مبلغ معامله (تومان)',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:rate,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'درصد کمیسیون',border:OutlineInputBorder())),const SizedBox(height:16),FilledButton(onPressed:(){setState(()=>result=(double.tryParse(amount.text.replaceAll(',',''))??0)*(double.tryParse(rate.text)??0)/100);},child:const Text('محاسبه')),const SizedBox(height:18),Text('مبلغ کمیسیون: ${result.toStringAsFixed(0)} تومان',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold,color:gold))])))));
