class PasswordDialog extends StatefulWidget { const PasswordDialog({super.key}); @override State<PasswordDialog> createState()=>_PasswordDialogState(); }
class _PasswordDialogState extends State<PasswordDialog>{final p=TextEditingController();@override Widget build(BuildContext c)=>AlertDialog(title:const Text('تغییر رمز عبور'),content:TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'رمز جدید',border:OutlineInputBorder())),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('انصراف')),FilledButton(onPressed:()async{if(p.text.length<4)return;final u=await Store.users();for(final x in u){if(x.username==currentUser?.username)x.password=hashPass(p.text);}await Store.saveUsers(u);if(c.mounted)Navigator.pop(c);},child:const Text('ذخیره'))]);}
